<!doctype html><html><head><meta charset="utf-8"><style>body{font:12px Arial;color:#111827}h1,h2{color:#0f172a;font-weight:800}table{width:100%;border-collapse:collapse}th,td{border:1px solid #cbd5e1;padding:8px;text-align:left}th{background:#e2e8f0}.card{border-left:4px solid #2563eb;background:#f8fafc;padding:10px;margin:9px 0}.muted{color:#475569}</style></head><body><h1>Savings Offers</h1><p class="muted">Personalized from <?= e($from->format('d M Y')) ?> to <?= e($to->format('d M Y')) ?> · All amounts in BDT/Taka</p><h2>Your spending priorities for this period</h2><table><tr><th>Category</th><th>Period cost</th></tr><?php foreach($spending as $row): ?><tr><td><?= e($row['category']) ?></td><td>BDT <?= e(number_format((float)$row['amount'],2)) ?></td></tr><?php endforeach; ?><tr><th>Total</th><th>BDT <?= e(number_format($total,2)) ?></th></tr></table><h2>Official offer sources</h2><?php foreach($offers as $offer): ?><div class="card"><strong><?= e($offer['provider']) ?> — <?= e($offer['focus']) ?></strong><br><?= e($offer['source']) ?><br><a href="<?= e($offer['url']) ?>"><?= e($offer['url']) ?></a></div><?php endforeach; ?><h2>How these can reduce your cost</h2><?php foreach($advice as $item): ?><div class="card"><?= e($item) ?></div><?php endforeach; ?><p class="muted">Verify eligibility, minimum order, expiry date, and terms before using any promotion.</p></body></html>
